INSERT INTO producer_news (producer_id,posted_at,title,image_ref,body) SELECT 1, TIMESTAMP '2026-05-28 08:58','제철 콩 5월 산지 소식입니다~','콩','경북영천 권민성입니다~ 올해는 일조량이 풍부해 콩 품질이 예년보다 좋습니다. 경매장 시세는 올랐지만, 소비자분들께 신선하고 맛있는 콩을(를) 보내드린다는 자부심으로 합리적인 가격에 정직하게 판매하고 있습니다.' WHERE NOT EXISTS (SELECT 1 FROM producer_news WHERE producer_id=1 AND title='제철 콩 5월 산지 소식입니다~');
INSERT INTO producer_news (producer_id,posted_at,title,image_ref,body) SELECT 1, TIMESTAMP '2026-04-12 09:00','콩의 계절이 돌아왔습니다~','photo','콩의 계절이 다가왔습니다. 이번 해는 일조량이 풍부하여 경북영천 콩이(가) 무럭무럭 잘 자라고 있습니다. 작년 대비 생산량과 품질이 더 좋아졌습니다~ 산지의 신선함 그대로 정직하게 판매하겠습니다.' WHERE NOT EXISTS (SELECT 1 FROM producer_news WHERE producer_id=1 AND title='콩의 계절이 돌아왔습니다~');
INSERT INTO producer_news (producer_id,posted_at,title,image_ref,body) SELECT 1, TIMESTAMP '2026-03-07 08:56','봄을 알리는 첫 수확을 시작하였습니다~','콩','안녕하세요 생산자 권민성입니다~ 겨울 날씨가 포근하고 일조량이 좋아 수확을 조금 빨리 시작했습니다. 올해 생산량과 품질, 당도 모두 우수할 것으로 보입니다.' WHERE NOT EXISTS (SELECT 1 FROM producer_news WHERE producer_id=1 AND title='봄을 알리는 첫 수확을 시작하였습니다~');
INSERT INTO producer_reviews (producer_id,user_id,author_name,rating,item,body,created_at) SELECT 1,9010,'민지',5,'콩','경북영천에서 바로 받아서 그런지 정말 싱싱해요. 콩 이렇게 신선한 건 처음이에요. 재구매 의사 100%입니다!', TIMESTAMP '2026-05-30 10:00' WHERE NOT EXISTS (SELECT 1 FROM producer_reviews WHERE producer_id=1 AND author_name='민지' AND item='콩');
INSERT INTO producer_reviews (producer_id,user_id,author_name,rating,item,body,created_at) SELECT 1,9011,'재현',5,'봄동','포장도 꼼꼼하고 당일 수확이라 그런지 식감이 살아있어요. 가족들이 다 좋아하네요.', TIMESTAMP '2026-05-21 10:00' WHERE NOT EXISTS (SELECT 1 FROM producer_reviews WHERE producer_id=1 AND author_name='재현' AND item='봄동');
