INSERT INTO producer_news (producer_id,posted_at,title,image_ref,body) SELECT 5, TIMESTAMP '2026-05-28 08:58','제철 시금치 5월 산지 소식입니다~','시금치','강원평창 이수향입니다~ 올해는 일조량이 풍부해 시금치 품질이 예년보다 좋습니다. 경매장 시세는 올랐지만, 소비자분들께 신선하고 맛있는 시금치을(를) 보내드린다는 자부심으로 합리적인 가격에 정직하게 판매하고 있습니다.' WHERE NOT EXISTS (SELECT 1 FROM producer_news WHERE producer_id=5 AND title='제철 시금치 5월 산지 소식입니다~');
INSERT INTO producer_news (producer_id,posted_at,title,image_ref,body) SELECT 5, TIMESTAMP '2026-04-12 09:00','시금치의 계절이 돌아왔습니다~','photo','시금치의 계절이 다가왔습니다. 이번 해는 일조량이 풍부하여 강원평창 시금치이(가) 무럭무럭 잘 자라고 있습니다. 작년 대비 생산량과 품질이 더 좋아졌습니다~ 산지의 신선함 그대로 정직하게 판매하겠습니다.' WHERE NOT EXISTS (SELECT 1 FROM producer_news WHERE producer_id=5 AND title='시금치의 계절이 돌아왔습니다~');
INSERT INTO producer_news (producer_id,posted_at,title,image_ref,body) SELECT 5, TIMESTAMP '2026-03-07 08:56','봄을 알리는 첫 수확을 시작하였습니다~','시금치','안녕하세요 생산자 이수향입니다~ 겨울 날씨가 포근하고 일조량이 좋아 수확을 조금 빨리 시작했습니다. 올해 생산량과 품질, 당도 모두 우수할 것으로 보입니다.' WHERE NOT EXISTS (SELECT 1 FROM producer_news WHERE producer_id=5 AND title='봄을 알리는 첫 수확을 시작하였습니다~');
