INSERT INTO producer_reviews (producer_id,user_id,author_name,rating,item,body,created_at) SELECT 8,9082,'수안',4,'단호박','맛은 아주 좋은데 배송이 하루 늦었어요. 그래도 품질 보고 또 주문할 것 같습니다.', TIMESTAMP '2026-05-12 10:00' WHERE NOT EXISTS (SELECT 1 FROM producer_reviews WHERE producer_id=8 AND author_name='수안' AND item='단호박');
